// Merge a React Native style value into one plain object.
// A style can be an object, a falsy value, or an array of styles (arrays can nest).
function flattenStyle(style) {
  if (Array.isArray(style)) {
    return Object.assign(style[0], ...style.slice(1));
  }
  return style;
}

const card = { padding: 12, borderRadius: 12 };
console.log(flattenStyle([card, false, { padding: 8 }]));

solution.js:
function flattenStyle(style) {
  if (!style) return {};
  if (!Array.isArray(style)) return { ...style };
  const result = {};
  for (const entry of style) {
    Object.assign(result, flattenStyle(entry));
  }
  return result;
}

const card = { padding: 12, borderRadius: 12 };
console.log(flattenStyle([card, false, { padding: 8 }]));
